import type { GeneratedPolicy } from '@hfos/core';
import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { publicEnv } from '@/lib/env';

/**
 * The privacy policy and terms HandsFreeOS hosts for a business: `/legal/<business>/privacy`.
 *
 * Signed out, and plain on purpose — a carrier's reviewer opens this looking for one paragraph, and the
 * quickest page to read is the one most likely to be read. The words are generated by core from what the
 * business told the registration, including while it's still being filled in; the worker serves them.
 */
type LegalPage = { policy?: GeneratedPolicy; redirectTo?: string; business?: string };

const SLUG_RE = /^[A-Za-z0-9-]{1,80}$/;

/** A plain web address to link to, or null: anything else a business typed is never shown as a link. */
function webAddress(raw: string | undefined): URL | null {
  if (!raw) return null;
  try {
    const url = new URL(raw);
    return (url.protocol === 'https:' || url.protocol === 'http:') && !url.username && !url.password
      ? url
      : null;
  } catch {
    return null;
  }
}

async function fetchPolicy(site: string, kind: string): Promise<LegalPage | null> {
  if (!SLUG_RE.test(site) || (kind !== 'privacy' && kind !== 'terms')) return null;
  try {
    const res = await fetch(`${publicEnv.workerUrl}/public/legal/${site}/${kind}`, {
      // Briefly: the page follows the registration's answers as they're got ready (the worker's legalSourceOf).
      next: { revalidate: 60 },
    });
    if (!res.ok) return null;
    return (await res.json()) as LegalPage;
  } catch {
    return null;
  }
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ site: string; kind: string }>;
}): Promise<Metadata> {
  const { site, kind } = await params;
  const page = await fetchPolicy(site, kind);
  const title =
    page?.policy?.title ??
    (page?.business
      ? `${page.business} — ${kind === 'terms' ? 'Terms of Service' : 'Privacy Policy'}`
      : 'Policy');
  return { title, robots: { index: false } };
}

export default async function LegalPage({
  params,
}: {
  params: Promise<{ site: string; kind: string }>;
}) {
  const { site, kind } = await params;
  if (kind !== 'privacy' && kind !== 'terms') notFound();
  const page = await fetchPolicy(site, kind);
  if (!page) notFound();
  // A business with its own policy: every agreement box still links here, and here links on to it. Never a redirect:
  // the address is whatever the business typed, and our own domain mustn't send a browser anywhere on its say-so (a
  // stranger's link to app.handsfreeos.com could otherwise land on any site, a sign-in's tokens and all).
  const own = webAddress(page.redirectTo);
  if (own) {
    const business = page.business ?? 'This business';
    const what = kind === 'terms' ? 'terms of service' : 'privacy policy';
    return (
      <main className="mx-auto min-h-dvh max-w-[680px] bg-bg px-5 py-10 text-text">
        <h1 className="text-[24px] font-semibold">
          {business} — {kind === 'terms' ? 'Terms of Service' : 'Privacy Policy'}
        </h1>
        <p className="mt-3 text-[14.5px] leading-relaxed text-text-2">
          {business} keeps its own {what} on its website.
        </p>
        <p className="mt-5">
          <a
            href={own.toString()}
            rel="noopener noreferrer nofollow"
            className="text-[15px] font-semibold text-accent-text underline underline-offset-2"
          >
            Read the {what} at {own.host}
          </a>
        </p>
        <p className="mt-2 break-all text-[13px] text-text-3">{own.toString()}</p>
      </main>
    );
  }
  const policy = page.policy;
  if (!policy) notFound();
  return (
    <main className="mx-auto min-h-dvh max-w-[680px] bg-bg px-5 py-10 text-text">
      <h1 className="text-[24px] font-semibold">{policy.title}</h1>
      <p className="mt-3 text-[14.5px] leading-relaxed text-text-2">{policy.intro}</p>
      {policy.sections.map((section) => (
        <section key={section.heading} className="mt-7">
          <h2 className="text-[16px] font-semibold">{section.heading}</h2>
          {section.paragraphs.map((paragraph, i) => (
            <p
              key={i}
              className="mt-2 whitespace-pre-line text-[14.5px] leading-relaxed text-text-2"
            >
              {paragraph}
            </p>
          ))}
        </section>
      ))}
      <p className="mt-8 text-[13px] text-text-3">Last updated: {policy.updated}</p>
    </main>
  );
}
